/** Professional animated wallet stack shared by all four vault categories. */
public class CategoryActivity extends FragmentActivity {
 private final ExecutorService io=Executors.newSingleThreadExecutor();
 private final ArrayList<JSONObject> items=new ArrayList<>();
 private VaultRepository repo; private String group; private int index; private boolean ready;
 private FrameLayout active,rearNear,rearDeep; private TextView itemTitle,counter,side;private LinearLayout expiryList;
 private Bitmap faceImage,reverseImage,pageImage,rearNearImage,rearDeepImage; private float downX,downY; private boolean showingBack,longPressTriggered;private int currentPage,totalPages;
 private final android.os.Handler gestures=new android.os.Handler(android.os.Looper.getMainLooper());
 private final Runnable enlargeGesture=()->{if(ready&&(DocumentGroups.CARDS.equals(group)||DocumentGroups.ID.equals(group))){longPressTriggered=true;openLandscapeViewer();}};
 private String uploadKind;
 private final ActivityResultLauncher<String[]> uploadPicker=registerForActivityResult(new ActivityResultContracts.OpenDocument(),uri->{if(uri!=null&&"word".equals(uploadKind))importWordWithoutPreview(uri);else importSelected(uri);});
 private final ActivityResultLauncher<Intent> imagePicker=registerForActivityResult(new ActivityResultContracts.StartActivityForResult(),result->{if(result.getResultCode()==RESULT_OK&&result.getData()!=null)importSelected(result.getData().getData());});

 @Override public void onCreate(Bundle b){super.onCreate(b);Ui.safeScreen(this);Ui.lightBars(this);if(!Session.valid()){finish();return;}getOnBackPressedDispatcher().addCallback(this,new OnBackPressedCallback(true){@Override public void handleOnBackPressed(){goHome();}});group=getIntent().getStringExtra("group");if(group==null)group=DocumentGroups.DOCUMENTS;repo=new VaultRepository(this);build();load();}

 private void build(){
  LinearLayout page=VaultPageUi.page(this);LinearLayout bar=VaultPageUi.header(this,group,"Opening encrypted stack");if(!DocumentGroups.DOCUMENTS.equals(group)){FrameLayout details=VaultPageUi.iconButtonView(this,"details","Document Details");details.setOnClickListener(v->openDetailsWizard());LinearLayout.LayoutParams dp=new LinearLayout.LayoutParams(Ui.dp(this,36),Ui.dp(this,36));dp.rightMargin=Ui.dp(this,7);bar.addView(details,dp);}FrameLayout add=VaultPageUi.iconButtonView(this,"plus","Upload To "+group);add.setOnClickListener(this::uploadMenu);bar.addView(add,new LinearLayout.LayoutParams(Ui.dp(this,36),Ui.dp(this,36)));page.addView(bar);counter=Ui.text(this,"Opening Secure Stack…",10,Ui.MUTED);counter.setGravity(Gravity.END);page.addView(counter);String instructionText=(DocumentGroups.CARDS.equals(group)||DocumentGroups.ID.equals(group))?"Tap to flip · Flick to browse":DocumentGroups.DOCUMENTS.equals(group)?"First-page preview · Flick to browse":"Tap for next page · Flick to browse";TextView instruction=Ui.text(this,instructionText,11,Ui.MUTED);instruction.setGravity(Gravity.CENTER);instruction.setPadding(0,Ui.dp(this,7),0,Ui.dp(this,9));page.addView(instruction);

  int availableDp=Math.round(getResources().getDisplayMetrics().widthPixels/getResources().getDisplayMetrics().density)-46;
  int faceDp;
  if(DocumentGroups.CARDS.equals(group)||DocumentGroups.ID.equals(group))faceDp=Math.round(availableDp/1.586f);
  else if(DocumentGroups.CERTIFICATES.equals(group))faceDp=Math.round(availableDp/1.294f);
  else faceDp=Math.min(430,Math.round(availableDp*1.294f));
  int screenHeightDp=Math.round(getResources().getDisplayMetrics().heightPixels/getResources().getDisplayMetrics().density);faceDp=Math.min(faceDp,Math.max(210,screenHeightDp-330));
  int faceHeight=Ui.dp(this,faceDp);
  int deckHeight=faceHeight+Ui.dp(this,42);
  FrameLayout deck=new FrameLayout(this);deck.setClipChildren(false);
  rearDeep=layer(.56f,.91f,31);rearNear=layer(.78f,.96f,17);deck.addView(rearDeep,params(faceHeight,18));deck.addView(rearNear,params(faceHeight,9));
  active=new FrameLayout(this);active.setBackground(Ui.stroke(Color.WHITE,Ui.dp(this,1),Ui.GOLD,Ui.dp(this,22)));active.setClipToOutline(true);active.setElevation(Ui.dp(this,11));active.setCameraDistance(Ui.dp(this,9000));active.setOnClickListener(v->flip());active.setOnTouchListener((v,e)->{int action=e.getActionMasked();if(action==MotionEvent.ACTION_DOWN){downX=e.getX();downY=e.getY();longPressTriggered=false;if(DocumentGroups.CARDS.equals(group)||DocumentGroups.ID.equals(group))gestures.postDelayed(enlargeGesture,430);return true;}if(action==MotionEvent.ACTION_MOVE){if(Math.abs(e.getX()-downX)>Ui.dp(this,16)||Math.abs(e.getY()-downY)>Ui.dp(this,16))gestures.removeCallbacks(enlargeGesture);return true;}if(action==MotionEvent.ACTION_UP){gestures.removeCallbacks(enlargeGesture);if(longPressTriggered)return true;float delta=e.getY()-downY;if(delta>Ui.dp(this,42))next();else if(delta<-Ui.dp(this,42))previous();else v.performClick();return true;}if(action==MotionEvent.ACTION_CANCEL){gestures.removeCallbacks(enlargeGesture);return true;}return true;});deck.addView(active,params(faceHeight,0));page.addView(deck,new LinearLayout.LayoutParams(-1,deckHeight));
  itemTitle=Ui.title(this,"",18);itemTitle.setGravity(Gravity.CENTER);page.addView(itemTitle);side=Ui.text(this,"Encrypted On This Phone",11,Ui.MUTED);side.setGravity(Gravity.CENTER);side.setPadding(0,Ui.dp(this,3),0,Ui.dp(this,8));page.addView(side);LinearLayout actions=new LinearLayout(this);actions.setGravity(Gravity.CENTER);String[] actionNames={"Edit","Crop","Export"},actionIcons={"edit","crop","share"};for(int i=0;i<3;i++){int selected=i;LinearLayout action=Ui.column(this);action.setGravity(Gravity.CENTER);action.setBackground(Ui.stroke(Ui.SURFACE,Ui.dp(this,1),Ui.BORDER,Ui.dp(this,13)));VaultIconView glyph=new VaultIconView(this).setIcon(actionIcons[i]).setColor(Ui.TEAL);action.addView(glyph,new LinearLayout.LayoutParams(Ui.dp(this,22),Ui.dp(this,22)));TextView label=Ui.text(this,actionNames[i],10,Ui.INK);label.setGravity(Gravity.CENTER);action.addView(label);action.setOnClickListener(v->{if(selected==0)editMetadata();else if(selected==1)cropPrompt();else openDocument();});LinearLayout.LayoutParams ap=new LinearLayout.LayoutParams(0,Ui.dp(this,55),1);if(i>0)ap.leftMargin=Ui.dp(this,7);actions.addView(action,ap);}page.addView(actions);page.addView(VaultPageUi.sectionHead(this,"Expired Soon","Title And Expiry Date"));expiryList=Ui.column(this);page.addView(expiryList);setContentView(VaultPageUi.screen(this,page,"vault"));
 }

 private FrameLayout layer(float alpha,float scale,int drop){FrameLayout v=new FrameLayout(this);v.setBackground(Ui.stroke(DocumentGroups.color(group),Ui.dp(this,1),0xffbfd4cf,Ui.dp(this,22)));v.setClipToOutline(true);v.setAlpha(alpha);v.setScaleX(scale);v.setTranslationY(Ui.dp(this,drop));v.setElevation(Ui.dp(this,3));return v;}
 private FrameLayout.LayoutParams params(int h,int top){FrameLayout.LayoutParams p=new FrameLayout.LayoutParams(-1,h,Gravity.TOP|Gravity.CENTER_HORIZONTAL);p.setMargins(Ui.dp(this,5),Ui.dp(this,top),Ui.dp(this,5),0);return p;}
 private void load(){ready=false;io.execute(()->{try{JSONArray all=repo.all();ArrayList<JSONObject> dated=ExpiryUi.dated(all,group);items.clear();for(int i=all.length()-1;i>=0;i--){JSONObject d=all.optJSONObject(i);if(d!=null&&group.equals(DocumentGroups.fromCategory(d.optString("category"))))items.add(d);}runOnUiThread(()->{renderExpiry(dated);if(items.isEmpty())empty();else{index=0;show(false);}});}catch(Exception e){runOnUiThread(()->Ui.toast(this,"Could Not Open This Category"));}});}

 private void show(boolean animate){
  ready=false;showingBack=false;currentPage=0;releaseImages();active.removeAllViews();rearNear.removeAllViews();rearDeep.removeAllViews();ProgressBar p=new ProgressBar(this);active.addView(p,new FrameLayout.LayoutParams(Ui.dp(this,46),Ui.dp(this,46),Gravity.CENTER));
  JSONObject d=items.get(index);itemTitle.setText(d.optString("title","Document"));counter.setText((index+1)+" Of "+items.size());JSONArray pages=d.optJSONArray("pages");int total=pages==null?0:pages.length();totalPages=total;side.setText(total+" Encrypted Page"+(total==1?"":"s"));
  if(animate){active.setAlpha(0);active.setTranslationY(-Ui.dp(this,46));active.setRotation(-4);}
  final int requested=index;io.execute(()->{try{Bitmap[] decoded=new Bitmap[4];boolean originalWord=d.optString("originalMime").contains("wordprocessingml"),hasPdfPreview="application/pdf".equals(d.optString("previewMime"));decoded[0]=originalWord&&!hasPdfPreview?wordCover(d.optString("title","Word Document")):decode(repo.page(d,0));if(total>1&&(!originalWord||hasPdfPreview))decoded[1]=decode(repo.page(d,1));if(items.size()>1){JSONObject next=items.get((requested+1)%items.size());boolean word=next.optString("originalMime").contains("wordprocessingml")&&!"application/pdf".equals(next.optString("previewMime"));decoded[2]=word?wordCover(next.optString("title","Word Document")):decode(repo.page(next,0));}if(items.size()>2){JSONObject next=items.get((requested+2)%items.size());boolean word=next.optString("originalMime").contains("wordprocessingml")&&!"application/pdf".equals(next.optString("previewMime"));decoded[3]=word?wordCover(next.optString("title","Word Document")):decode(repo.page(next,0));}runOnUiThread(()->{if(isFinishing()||requested!=index){for(Bitmap b:decoded)if(b!=null)b.recycle();return;}faceImage=decoded[0];reverseImage=decoded[1];rearNearImage=decoded[2];rearDeepImage=decoded[3];String badge=originalWord&&!hasPdfPreview?"DOCX":(DocumentGroups.CARDS.equals(group)||DocumentGroups.ID.equals(group))?"FRONT":"PAGE 1";putImage(active,faceImage,badge);putImage(rearNear,rearNearImage,null);putImage(rearDeep,rearDeepImage,null);ready=true;if(animate)active.animate().alpha(1).translationY(0).rotation(0).setDuration(165).start();});}catch(Exception ex){runOnUiThread(()->{active.removeAllViews();TextView err=Ui.text(this,"Could Not Decrypt This Item",15,0xffb3261e);err.setGravity(Gravity.CENTER);active.addView(err,new FrameLayout.LayoutParams(-1,-1));});}});
 }
 private Bitmap decode(byte[] raw){BitmapFactory.Options bounds=new BitmapFactory.Options();bounds.inJustDecodeBounds=true;BitmapFactory.decodeByteArray(raw,0,raw.length,bounds);int s=1;while(Math.max(bounds.outWidth,bounds.outHeight)/s>1800)s*=2;BitmapFactory.Options o=new BitmapFactory.Options();o.inSampleSize=s;return BitmapFactory.decodeByteArray(raw,0,raw.length,o);}
 private Bitmap wordCover(String title){Bitmap bitmap=Bitmap.createBitmap(1200,1600,Bitmap.Config.ARGB_8888);Canvas canvas=new Canvas(bitmap);canvas.drawColor(0xfffbfcff);Paint band=new Paint(Paint.ANTI_ALIAS_FLAG);band.setColor(0xff185abd);canvas.drawRect(0,0,1200,330,band);Paint mark=new Paint(Paint.ANTI_ALIAS_FLAG);mark.setColor(Color.WHITE);mark.setTextAlign(Paint.Align.CENTER);mark.setTypeface(Typeface.create(Typeface.SANS_SERIF,Typeface.BOLD));mark.setTextSize(190);canvas.drawText("W",600,235,mark);Paint heading=new Paint(Paint.ANTI_ALIAS_FLAG);heading.setColor(0xff10253f);heading.setTextAlign(Paint.Align.CENTER);heading.setTypeface(Typeface.create(Typeface.SANS_SERIF,Typeface.BOLD));heading.setTextSize(66);canvas.drawText("Microsoft Word Document",600,520,heading);Paint name=new Paint(Paint.ANTI_ALIAS_FLAG);name.setColor(0xff465b70);name.setTextAlign(Paint.Align.CENTER);name.setTextSize(48);String value=title.length()>34?title.substring(0,31)+"…":title;canvas.drawText(value,600,625,name);Paint rule=new Paint(Paint.ANTI_ALIAS_FLAG);rule.setColor(0xffd7e3f5);rule.setStrokeWidth(4);for(int y=770;y<=1110;y+=85)canvas.drawLine(190,y,1010,y,rule);Paint note=new Paint(Paint.ANTI_ALIAS_FLAG);note.setColor(0xff185abd);note.setTextAlign(Paint.Align.CENTER);note.setTypeface(Typeface.create(Typeface.SANS_SERIF,Typeface.BOLD));note.setTextSize(45);canvas.drawText("Tap To Open The Original In Word",600,1370,note);return bitmap;}
 private void putImage(FrameLayout frame,Bitmap bitmap,String badge){frame.removeAllViews();if(bitmap==null)return;ImageView view=new ImageView(this);view.setImageBitmap(bitmap);view.setScaleType(ImageView.ScaleType.FIT_CENTER);view.setBackgroundColor(Color.WHITE);frame.addView(view,new FrameLayout.LayoutParams(-1,-1));if(badge!=null){TextView seal=Ui.text(this,badge,10,Color.WHITE);seal.setTypeface(null,android.graphics.Typeface.BOLD);seal.setGravity(Gravity.CENTER);seal.setBackground(Ui.bg(0xdd061f3b,Ui.dp(this,12)));FrameLayout.LayoutParams bp=new FrameLayout.LayoutParams(Ui.dp(this,72),Ui.dp(this,25),Gravity.TOP|Gravity.END);bp.setMargins(0,Ui.dp(this,12),Ui.dp(this,12),0);frame.addView(seal,bp);}}
 private void next(){if(!ready||items.size()<2){active.animate().translationY(Ui.dp(this,10)).setDuration(60).withEndAction(()->active.animate().translationY(0).setDuration(80).start()).start();return;}ready=false;active.animate().translationY(Ui.dp(this,275)).rotation(4).alpha(0).setDuration(145).withEndAction(()->{index=(index+1)%items.size();show(true);}).start();}
 private void previous(){if(!ready||items.size()<2){active.animate().translationY(-Ui.dp(this,10)).setDuration(60).withEndAction(()->active.animate().translationY(0).setDuration(80).start()).start();return;}ready=false;active.animate().translationY(-Ui.dp(this,275)).rotation(-4).alpha(0).setDuration(145).withEndAction(()->{index=(index-1+items.size())%items.size();show(true);}).start();}
 private void flip(){if(DocumentGroups.DOCUMENTS.equals(group)){if(ready)edit();return;}if(!(DocumentGroups.CARDS.equals(group)||DocumentGroups.ID.equals(group))){nextPage();return;}if(!ready||reverseImage==null){active.animate().scaleX(.98f).scaleY(.98f).setDuration(85).withEndAction(()->active.animate().scaleX(1).scaleY(1).setDuration(110).start()).start();return;}active.setEnabled(false);active.animate().rotationY(90).setDuration(135).withEndAction(()->{showingBack=!showingBack;putImage(active,showingBack?reverseImage:faceImage,showingBack?"BACK":"FRONT");side.setText(showingBack?"Back Of Card":"Front Of Card");active.setRotationY(-90);active.animate().rotationY(0).setDuration(150).withEndAction(()->active.setEnabled(true)).start();}).start();}
 private void nextPage(){if(!ready||totalPages<2){active.animate().scaleX(.98f).scaleY(.98f).setDuration(65).withEndAction(()->active.animate().scaleX(1).scaleY(1).setDuration(80).start()).start();return;}ready=false;int target=(currentPage+1)%totalPages;active.animate().rotationY(90).setDuration(125).withEndAction(()->{if(target==0)showDocumentPage(faceImage,target);else if(target==1)showDocumentPage(reverseImage,target);else{JSONObject document=items.get(index);int requested=index;io.execute(()->{try{Bitmap decoded=decode(repo.page(document,target));runOnUiThread(()->{if(isFinishing()||requested!=index){decoded.recycle();return;}if(pageImage!=null&&!pageImage.isRecycled())pageImage.recycle();pageImage=decoded;showDocumentPage(pageImage,target);});}catch(Exception error){runOnUiThread(()->{ready=true;active.setRotationY(0);Ui.toast(this,"Could Not Open This Page");});}});}}).start();}
 private void showDocumentPage(Bitmap bitmap,int page){currentPage=page;putImage(active,bitmap,"PAGE "+(page+1));side.setText("Page "+(page+1)+" Of "+totalPages);active.setRotationY(-90);active.animate().rotationY(0).setDuration(145).withEndAction(()->ready=true).start();}
 private void edit(){openDocument();}
 private void openDocument(){if(items.isEmpty())return;JSONObject d=items.get(index);startActivity(new Intent(this,DocumentActivity.class).putExtra("id",d.optString("id")));}
 private void openDetailsWizard(){if(items.isEmpty()){Ui.toast(this,"Save A Document Before Adding Details");return;}JSONObject d=items.get(index);startActivity(new Intent(this,DocumentDetailsWizardActivity.class).putExtra("id",d.optString("id")).putExtra("group",group));}
 private void editMetadata(){if(items.isEmpty())return;JSONObject d=items.get(index);LinearLayout box=Ui.column(this);box.setPadding(Ui.dp(this,18),Ui.dp(this,5),Ui.dp(this,18),0);EditText title=Ui.field(this,"Document title",false);title.setText(d.optString("title"));box.addView(title,new LinearLayout.LayoutParams(-1,Ui.dp(this,54)));Spinner category=new Spinner(this);String[] values={DocumentGroups.ID,DocumentGroups.CARDS,DocumentGroups.CERTIFICATES,DocumentGroups.DOCUMENTS};category.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,values));for(int i=0;i<values.length;i++)if(values[i].equals(DocumentGroups.fromCategory(d.optString("category"))))category.setSelection(i);LinearLayout.LayoutParams cp=new LinearLayout.LayoutParams(-1,Ui.dp(this,54));cp.topMargin=Ui.dp(this,10);box.addView(category,cp);AlertDialog dialog=new AlertDialog.Builder(this).setTitle("Edit Document").setView(box).setNegativeButton("Cancel",null).setPositiveButton("Save",null).create();dialog.setOnShowListener(x->dialog.getButton(-1).setOnClickListener(v->{String name=title.getText().toString().trim();if(name.isEmpty()){title.setError("Enter a title");return;}String target=values[category.getSelectedItemPosition()];dialog.getButton(-1).setEnabled(false);io.execute(()->{try{repo.rename(d.getString("id"),name,target);runOnUiThread(()->{dialog.dismiss();load();Ui.toast(this,"Document Updated");});}catch(Exception error){runOnUiThread(()->{dialog.getButton(-1).setEnabled(true);Ui.toast(this,"Could Not Update The Document");});}});}));dialog.show();dialog.getWindow().setSoftInputMode(WindowManager.LayoutParams.SOFT_INPUT_ADJUST_RESIZE);}
 private void cropPrompt(){if(items.isEmpty())return;JSONObject d=items.get(index);String[] choices={"Front","Back","Cancel"};new AlertDialog.Builder(this).setTitle("Crop Which Side?").setItems(choices,(dialog,which)->{if(which==2)return;JSONArray pages=d.optJSONArray("pages");int page=which;if(pages==null||page>=pages.length()){Ui.toast(this,which==1?"No Back Page Is Saved":"No Croppable Page Is Available");return;}startActivity(new Intent(this,EditDocumentActivity.class).putExtra("id",d.optString("id")).putExtra("page",page));}).show();}
 private void renderExpiry(ArrayList<JSONObject> dated){expiryList.removeAllViews();if(dated.isEmpty()){expiryList.addView(VaultPageUi.notice(this,"✓","No Expiry Dates Saved","Add one from Document Details",Ui.SOFT,Ui.TEAL));return;}long now=System.currentTimeMillis();for(JSONObject item:dated){boolean urgent=ExpiryUi.withinYear(item,now);LinearLayout row=VaultPageUi.iconRow(this,"clock",item.optString("title","Document"),ExpiryUi.dateLine(item));if(urgent)tint(row,0xffc62828);row.setOnClickListener(v->startActivity(new Intent(this,DocumentActivity.class).putExtra("id",item.optString("id"))));VaultPageUi.addRow(expiryList,row);}}
 private void tint(View view,int color){if(view instanceof TextView)((TextView)view).setTextColor(color);if(view instanceof ViewGroup){ViewGroup group=(ViewGroup)view;for(int i=0;i<group.getChildCount();i++)tint(group.getChildAt(i),color);}}
 private void uploadMenu(View anchor){String[] options={"Upload Image From Gallery","Upload PDF","Upload Word Document (.docx)"};new AlertDialog.Builder(this).setTitle("Upload To "+group).setItems(options,(dialog,which)->{if(which==0&&(DocumentGroups.CARDS.equals(group)||DocumentGroups.ID.equals(group))){startActivity(new Intent(this,CardImportWizardActivity.class).putExtra("group",group));}else if(which==0){uploadKind="image";openGallery();}else if(which==1){uploadKind="pdf";uploadPicker.launch(new String[]{"application/pdf"});}else{uploadKind="word";uploadPicker.launch(new String[]{"application/vnd.openxmlformats-officedocument.wordprocessingml.document"});}}).show();}
 private void openGallery(){Intent intent=new Intent(Intent.ACTION_PICK,MediaStore.Images.Media.EXTERNAL_CONTENT_URI).setType("image/*");Intent samsung=new Intent(intent).setPackage("com.sec.android.gallery3d");imagePicker.launch(samsung.resolveActivity(getPackageManager())!=null?samsung:intent);}
 private void importSelected(android.net.Uri uri){if(uri==null)return;ProgressDialog wait=new ProgressDialog(this);wait.setCancelable(false);wait.setMessage("Preparing Secure Preview…");wait.show();String kind=uploadKind==null?"image":uploadKind;io.execute(()->{try{DocumentImporter importer=new DocumentImporter(this);ArrayList<android.net.Uri> pages=importer.convert(uri,kind);String suggested=importer.displayName(uri),sourceName=importer.sourceName(uri);runOnUiThread(()->{wait.dismiss();saveImported(pages,suggested,uri,sourceName,kind);});}catch(Exception error){runOnUiThread(()->{wait.dismiss();Ui.toast(this,error.getMessage()==null?"Could Not Import This File":error.getMessage());});}});}
 private void importWordWithoutPreview(android.net.Uri wordUri){DocumentImporter importer=new DocumentImporter(this);saveImported(new ArrayList<>(),importer.displayName(wordUri),wordUri,importer.sourceName(wordUri),"word");}
 private void saveImported(ArrayList<android.net.Uri> pages,String suggested,android.net.Uri source,String sourceName,String kind){LinearLayout box=Ui.column(this);box.setPadding(Ui.dp(this,18),Ui.dp(this,5),Ui.dp(this,18),0);EditText title=Ui.field(this,"Saved item name",false);title.setText(suggested);box.addView(title,new LinearLayout.LayoutParams(-1,Ui.dp(this,54)));boolean word="word".equals(kind),preserveOriginal=word||"pdf".equals(kind);String detail=word?"The original Word file will be encrypted unchanged. No content preview will be created.":pages.size()+" preview page"+(pages.size()==1?"":"s")+" will be encrypted in "+group+"."+(preserveOriginal?" The original file will also be encrypted without changing its layout.":"");TextView summary=Ui.text(this,detail,13,Ui.TEAL);summary.setPadding(2,Ui.dp(this,12),0,0);box.addView(summary);AlertDialog dialog=new AlertDialog.Builder(this).setTitle(word?"Save Word Document":"Save Uploaded File").setView(box).setNegativeButton("Discard",(d,w)->DocumentImporter.cleanup(pages)).setPositiveButton("Encrypt & Save",null).create();dialog.setOnCancelListener(d->DocumentImporter.cleanup(pages));dialog.setOnShowListener(x->dialog.getButton(-1).setOnClickListener(v->{String name=title.getText().toString().trim();if(name.isEmpty()){title.setError("Give this item a name");return;}dialog.getButton(-1).setEnabled(false);io.execute(()->{try{String mime=word?"application/vnd.openxmlformats-officedocument.wordprocessingml.document":"pdf".equals(kind)?"application/pdf":null;repo.add(name,group,pages,preserveOriginal?source:null,mime,preserveOriginal?sourceName:null,false);DocumentImporter.cleanup(pages);runOnUiThread(()->{dialog.dismiss();load();Ui.toast(this,"Upload Encrypted And Saved");});}catch(Exception error){runOnUiThread(()->{dialog.getButton(-1).setEnabled(true);Ui.toast(this,"Could Not Save This Upload");});}});}));dialog.show();dialog.getWindow().setSoftInputMode(WindowManager.LayoutParams.SOFT_INPUT_ADJUST_RESIZE);}
 private void openLandscapeViewer(){if(items.isEmpty())return;JSONObject d=items.get(index);startActivity(new Intent(this,CardFullscreenActivity.class).putExtra("id",d.optString("id")).putExtra("page",showingBack?1:0).putExtra("title",d.optString("title",group)));}
 private void goHome(){Intent home=new Intent(this,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_CLEAR_TOP|Intent.FLAG_ACTIVITY_SINGLE_TOP);startActivity(home);finish();}
 private void empty(){active.removeAllViews();rearNear.removeAllViews();rearDeep.removeAllViews();TextView t=Ui.text(this,"No "+group+" Saved Yet\n\nReturn To My Vault And Scan Your First Item",17,Ui.MUTED);t.setGravity(Gravity.CENTER);active.addView(t,new FrameLayout.LayoutParams(-1,-1));counter.setText("0 Saved Items");itemTitle.setText("Your Stack Is Ready");side.setText("Encrypted On This Phone");}
 private void releaseImages(){for(Bitmap b:new Bitmap[]{faceImage,reverseImage,pageImage,rearNearImage,rearDeepImage})if(b!=null&&!b.isRecycled())b.recycle();faceImage=reverseImage=pageImage=rearNearImage=rearDeepImage=null;}
 @Override protected void onResume(){super.onResume();if(!Session.valid())finish();else if(!items.isEmpty())load();}
 @Override public boolean dispatchTouchEvent(MotionEvent e){if(Session.valid())Session.touch();return super.dispatchTouchEvent(e);}
 @Override protected void onDestroy(){gestures.removeCallbacks(enlargeGesture);super.onDestroy();io.shutdownNow();releaseImages();}
}
